import os
import sys


def normalize(line):
    s = line.strip().lower()
    if not s:
        return None, False
    if s.count("@") != 1:
        return None, True
    local, domain = s.split("@")
    if not local or not domain:
        return None, True
    if "." not in domain or domain.startswith(".") or domain.endswith("."):
        return None, True
    if domain == "gmail.com":
        plus = local.find("+")
        if plus != -1:
            local = local[:plus]
        local = local.replace(".", "")
    return local + "@" + domain, False


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "emails.txt")
    with open(path, "rb") as f:
        data = f.read()
    text = data.decode("utf-8", errors="surrogateescape")
    seen = set()
    invalid = 0
    for line in text.splitlines():
        addr, bad = normalize(line)
        if bad:
            invalid += 1
        elif addr is not None:
            seen.add(addr)
    out = sys.stdout.buffer
    for addr in sorted(seen, key=lambda a: a.encode("utf-8", errors="surrogateescape")):
        out.write(addr.encode("utf-8", errors="surrogateescape") + b"\n")
    out.write(("invalid %d\n" % invalid).encode("ascii"))
    out.flush()


if __name__ == "__main__":
    main()

import os
import re


def to_roman(n):
    table = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    ]
    out = []
    for v, s in table:
        while n >= v:
            out.append(s)
            n -= v
    return "".join(out)


VALS = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def from_roman(s):
    total = 0
    for i, ch in enumerate(s):
        v = VALS[ch]
        if i + 1 < len(s) and VALS[s[i + 1]] > v:
            total -= v
        else:
            total += v
    return total


def convert(line):
    if re.fullmatch(r"[+-]?[0-9]+", line):
        n = int(line)
        if 1 <= n <= 3999:
            return to_roman(n)
        return "invalid"
    if re.fullmatch(r"[IVXLCDM]+", line):
        n = from_roman(line)
        if 1 <= n <= 3999 and to_roman(n) == line:
            return str(n)
        return "invalid"
    return "invalid"


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "numbers.txt")
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        lines = f.read().splitlines()
    out = []
    for raw in lines:
        line = raw.strip()
        if not line:
            continue
        out.append(f"{line} = {convert(line)}")
    if out:
        print("\n".join(out))


if __name__ == "__main__":
    main()

import os
import sys


def check(line):
    pairs = {'(': ')', '[': ']', '{': '}'}
    closers = set(pairs.values())
    stack = []
    for i, ch in enumerate(line, 1):
        if ch in pairs:
            stack.append(pairs[ch])
        elif ch in closers:
            if not stack:
                return "col %d: unexpected %s" % (i, ch)
            expected = stack.pop()
            if expected != ch:
                return "col %d: expected %s, found %s" % (i, expected, ch)
    if stack:
        return "unclosed %s" % stack[-1]
    return "ok"


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "snippets.txt")
    with open(path, "r", encoding="ascii", errors="replace", newline="") as f:
        data = f.read()
    if data == "":
        return
    lines = data.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    out = []
    for line in lines:
        if line.endswith("\r"):
            line = line[:-1]
        out.append(check(line))
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


if __name__ == "__main__":
    main()

import os
import re
import sys


def main():
    base = os.environ["INPUT"]
    path = os.path.join(base, "timings.log")
    with open(path, "rb") as f:
        data = f.read()
    text = data.decode("utf-8", errors="surrogateescape")
    int_re = re.compile(r"[+-]?[0-9]+")
    groups = {}
    for line in text.splitlines():
        parts = line.split()
        if len(parts) != 3:
            continue
        method, p, ms = parts
        if not int_re.fullmatch(ms):
            continue
        groups.setdefault((method, p), []).append(int(ms))

    def bkey(k):
        return (
            k[0].encode("utf-8", errors="surrogateescape"),
            k[1].encode("utf-8", errors="surrogateescape"),
        )

    out = []
    for key in sorted(groups, key=bkey):
        times = sorted(groups[key])
        n = len(times)

        def pct(pv):
            idx = (pv * n + 99) // 100
            if idx < 1:
                idx = 1
            if idx > n:
                idx = n
            return times[idx - 1]

        out.append(
            "%s %s count=%d p50=%d p95=%d max=%d"
            % (key[0], key[1], n, pct(50), pct(95), times[-1])
        )
    s = "".join(line + "\n" for line in out)
    sys.stdout.buffer.write(s.encode("utf-8", errors="surrogateescape"))


if __name__ == "__main__":
    main()

import os
import sys
import heapq


def main():
    base = os.environ.get("INPUT", ".")
    path = os.path.join(base, "routes.txt")
    with open(path, "rb") as f:
        data = f.read()
    text = data.decode("utf-8", errors="surrogateescape")

    adj = {}
    trips = []

    def key(name):
        return name.encode("utf-8", errors="surrogateescape")

    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        if parts[0] == "road" and len(parts) == 4:
            a, b, c = parts[1], parts[2], parts[3]
            try:
                cost = int(c)
            except ValueError:
                continue
            for u, v in ((a, b), (b, a)):
                d = adj.setdefault(u, {})
                if v not in d or cost < d[v]:
                    d[v] = cost
        elif parts[0] == "trip" and len(parts) == 3:
            trips.append((parts[1], parts[2]))

    cache = {}

    def dists_to(t):
        if t in cache:
            return cache[t]
        dist = {t: 0}
        pq = [(0, t)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist.get(u, float("inf")):
                continue
            for v, w in adj.get(u, {}).items():
                nd = d + w
                if nd < dist.get(v, float("inf")):
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))
        cache[t] = dist
        return dist

    out = []
    for x, y in trips:
        if x == y:
            out.append(f"{x} 0")
            continue
        dist = dists_to(y)
        if x not in dist:
            out.append(f"{x} {y} unreachable")
            continue
        route = [x]
        u = x
        while u != y:
            best = None
            for v, w in adj.get(u, {}).items():
                if v in dist and w + dist[v] == dist[u]:
                    if best is None or key(v) < key(best):
                        best = v
            route.append(best)
            u = best
        out.append(" -> ".join(route) + f" {dist[x]}")

    sys.stdout.buffer.write(
        ("\n".join(out) + ("\n" if out else "")).encode("utf-8", errors="surrogateescape")
    )


if __name__ == "__main__":
    main()

import json
import os
import sys


def merge(base, override):
    result = dict(base) if isinstance(base, dict) else {}
    for key, val in override.items():
        if val is None:
            result.pop(key, None)
        elif isinstance(val, dict):
            existing = result.get(key)
            result[key] = merge(existing if isinstance(existing, dict) else {}, val)
        else:
            result[key] = val
    return result


def flatten(value, path, out):
    if isinstance(value, dict):
        if not value:
            out.append((path, "{}"))
            return
        for k, v in value.items():
            flatten(v, k if path is None else path + "." + k, out)
    elif isinstance(value, list):
        if not value:
            out.append((path, "[]"))
            return
        for i, v in enumerate(value):
            k = str(i)
            flatten(v, k if path is None else path + "." + k, out)
    else:
        out.append((path, json.dumps(value, ensure_ascii=False)))


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "base.json"), "rb") as f:
        base = json.loads(f.read().decode("utf-8"))
    with open(os.path.join(d, "override.json"), "rb") as f:
        override = json.loads(f.read().decode("utf-8"))
    if not isinstance(base, dict):
        base = {}
    if not isinstance(override, dict):
        override = {}
    merged = merge(base, override)
    out = []
    for k, v in merged.items():
        flatten(v, k, out)
    out.sort(key=lambda p: p[0].encode("utf-8"))
    data = "".join("%s=%s\n" % (p, v) for p, v in out)
    sys.stdout.buffer.write(data.encode("utf-8"))
    sys.stdout.flush()


if __name__ == "__main__":
    main()

import os
import sys


def main():
    in_dir = os.environ["INPUT"]
    out_dir = os.environ["OUT"]
    src = os.path.join(in_dir, "app.log")

    buckets = {"error": [], "warn": [], "info": []}
    level_map = {"ERROR": "error", "WARN": "warn", "WARNING": "warn", "INFO": "info"}
    other = 0

    try:
        with open(src, "r", encoding="utf-8", errors="surrogateescape", newline="") as f:
            data = f.read()
    except FileNotFoundError:
        data = ""

    lines = data.split("\n")
    if lines and lines[-1] == "":
        lines.pop()

    for raw in lines:
        line = raw[:-1] if raw.endswith("\r") else raw
        if line.strip() == "":
            continue
        fields = line.split()
        if len(fields) < 3:
            other += 1
            continue
        key = level_map.get(fields[1].upper())
        if key is None:
            other += 1
            continue
        buckets[key].append(line)

    for key in ("error", "warn", "info"):
        path = os.path.join(out_dir, key + ".log")
        with open(path, "w", encoding="utf-8", errors="surrogateescape", newline="") as f:
            for line in buckets[key]:
                f.write(line + "\n")

    out = sys.stdout
    out.write("error %d\n" % len(buckets["error"]))
    out.write("warn %d\n" % len(buckets["warn"]))
    out.write("info %d\n" % len(buckets["info"]))
    out.write("other %d\n" % other)
    out.flush()


if __name__ == "__main__":
    main()

import os
import sys


def list_files(path):
    names = []
    with os.scandir(path) as it:
        for entry in it:
            if entry.is_file(follow_symlinks=False) or entry.is_file():
                names.append(entry.name)
    return names


def read_bytes(path):
    with open(path, "rb") as f:
        return f.read()


def write_atomic(dst_dir, name, data):
    final = os.path.join(dst_dir, name)
    tmp = os.path.join(dst_dir, "." + name + ".synctmp")
    with open(tmp, "wb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, final)


def main():
    src = os.environ["SRC"]
    dst = os.environ["DST"]

    src_names = list_files(src)
    dst_names = set(list_files(dst))

    src_names.sort(key=lambda n: os.fsencode(n))

    out = []
    for name in src_names:
        data = read_bytes(os.path.join(src, name))
        if name not in dst_names:
            write_atomic(dst, name, data)
            out.append("added " + name)
        else:
            try:
                existing = read_bytes(os.path.join(dst, name))
            except OSError:
                existing = None
            if existing == data:
                out.append("same " + name)
            else:
                write_atomic(dst, name, data)
                out.append("updated " + name)

    kept = len(dst_names - set(src_names))
    out.append("kept %d" % kept)
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

import json
import os
import sys
import tempfile


def load_counts(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = f.read()
    except FileNotFoundError:
        return {}
    if not data.strip():
        return {}
    try:
        obj = json.loads(data)
    except ValueError:
        return {}
    if not isinstance(obj, dict):
        return {}
    result = {}
    for k, v in obj.items():
        try:
            result[str(k)] = int(v)
        except (TypeError, ValueError):
            continue
    return result


def save_counts(path, counts):
    directory = os.path.dirname(os.path.abspath(path)) or "."
    os.makedirs(directory, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix=".kv-", dir=directory)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(counts, f, sort_keys=True)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["COUNTS"]

    counts = load_counts(kv_path)

    visits_path = os.path.join(input_dir, "visits.txt")
    try:
        with open(visits_path, "r", encoding="utf-8", errors="surrogateescape") as f:
            for line in f:
                page = line.strip()
                if not page:
                    continue
                counts[page] = counts.get(page, 0) + 1
    except FileNotFoundError:
        pass

    save_counts(kv_path, counts)

    items = sorted(
        counts.items(),
        key=lambda kv: (-kv[1], kv[0].encode("utf-8", "surrogateescape")),
    )
    out = sys.stdout.buffer
    for page, total in items:
        out.write(page.encode("utf-8", "surrogateescape") + b" " + str(total).encode() + b"\n")
    out.flush()


if __name__ == "__main__":
    main()

import os
import sys
import json


def load(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            return data
    except (FileNotFoundError, ValueError, OSError):
        pass
    return {}


def save(path, data):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["USERS"]
    users = load(kv_path)

    with open(os.path.join(input_dir, "commands.txt"), "r", encoding="utf-8") as f:
        text = f.read()

    out = []
    changed = False
    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        parts = line.split()
        cmd = parts[0]
        n = len(parts)
        if cmd == "put" and n == 4:
            _, uid, name, email = parts
            users[uid] = {"name": name, "email": email}
            changed = True
            out.append("ok " + uid)
        elif cmd == "rename" and n == 3:
            _, uid, name = parts
            if uid in users:
                users[uid]["name"] = name
                changed = True
                out.append("ok " + uid)
            else:
                out.append("missing " + uid)
        elif cmd == "get" and n == 2:
            uid = parts[1]
            u = users.get(uid)
            if u is None:
                out.append("missing " + uid)
            else:
                obj = {"id": uid, "name": u["name"], "email": u["email"]}
                out.append(json.dumps(obj, separators=(",", ":"), ensure_ascii=False))
        elif cmd == "del" and n == 2:
            uid = parts[1]
            if uid in users:
                del users[uid]
                changed = True
                out.append("ok " + uid)
            else:
                out.append("missing " + uid)
        elif cmd == "count" and n == 1:
            out.append("count %d" % len(users))
        else:
            out.append("bad " + line)

    if changed or not os.path.exists(kv_path):
        save(kv_path, users)

    if out:
        sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

import json
import os
import sys
import tempfile


def _bad_constant(name):
    raise ValueError("invalid constant: " + name)


def parse_event(raw):
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        return None
    try:
        obj = json.loads(text, parse_constant=_bad_constant)
    except (ValueError, RecursionError):
        return None
    if not isinstance(obj, dict):
        return None
    eid = obj.get("id")
    acct = obj.get("account")
    cents = obj.get("cents")
    if not isinstance(eid, str) or not isinstance(acct, str):
        return None
    if not isinstance(cents, int) or isinstance(cents, bool):
        return None
    return eid, acct, cents


def load_state(path):
    if not os.path.exists(path):
        return set(), {}
    with open(path, "r", encoding="utf-8") as f:
        data = f.read()
    if not data.strip():
        return set(), {}
    obj = json.loads(data)
    applied = set(obj.get("applied", []))
    balances = {k: int(v) for k, v in obj.get("balances", {}).items()}
    return applied, balances


def save_state(path, applied, balances):
    d = os.path.dirname(os.path.abspath(path)) or "."
    os.makedirs(d, exist_ok=True)
    payload = json.dumps(
        {"applied": sorted(applied), "balances": balances},
        ensure_ascii=True,
    )
    fd, tmp = tempfile.mkstemp(dir=d, prefix=".kvtmp-")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(payload)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def main():
    input_dir = os.environ["INPUT"]
    state_path = os.environ["STATE"]

    applied_ids, balances = load_state(state_path)

    events_path = os.path.join(input_dir, "events.jsonl")
    try:
        with open(events_path, "rb") as f:
            content = f.read()
    except FileNotFoundError:
        content = b""

    n_applied = n_dup = n_rej = 0
    for raw in content.split(b"\n"):
        if raw.endswith(b"\r"):
            raw = raw[:-1]
        if not raw.strip():
            continue
        ev = parse_event(raw)
        if ev is None:
            n_rej += 1
            continue
        eid, acct, cents = ev
        if eid in applied_ids:
            n_dup += 1
            continue
        applied_ids.add(eid)
        balances[acct] = balances.get(acct, 0) + cents
        n_applied += 1

    save_state(state_path, applied_ids, balances)

    out = ["applied %d duplicate %d rejected %d" % (n_applied, n_dup, n_rej)]
    for acct in sorted(balances, key=lambda a: a.encode("utf-8", "surrogatepass")):
        out.append("%s %d" % (acct, balances[acct]))
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

import json
import os
import sys


def load_state(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            return data
    except (FileNotFoundError, ValueError, OSError):
        pass
    return {}


def save_state(path, state):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(state, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)


def main():
    input_dir = os.environ["INPUT"]
    limits_path = os.environ["LIMITS"]

    state = load_state(limits_path)
    # state: client -> [window, count]
    out = []

    req_path = os.path.join(input_dir, "requests.txt")
    try:
        with open(req_path, "r", encoding="utf-8", errors="replace") as f:
            lines = f.read().splitlines()
    except FileNotFoundError:
        lines = []

    for line in lines:
        parts = line.split()
        if len(parts) != 2:
            continue
        try:
            ts = int(parts[0])
        except ValueError:
            continue
        client = parts[1]
        window = ts // 60

        entry = state.get(client)
        if (
            not isinstance(entry, list)
            or len(entry) != 2
            or entry[0] != window
        ):
            entry = [window, 0]

        if entry[1] < 3:
            entry[1] += 1
            decision = "allow"
        else:
            decision = "deny"
        state[client] = entry
        out.append(f"{parts[0]} {client} {decision}")

    save_state(limits_path, state)
    if out:
        sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

import json
import os
import re
import threading
from http.server import BaseHTTPRequestHandler, HTTPServer

KV_PATH = os.environ["COUNTS"]
NAME_RE = re.compile(r"[a-z0-9-]{1,32}")
lock = threading.Lock()


def load():
    try:
        with open(KV_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            return {str(k): int(v) for k, v in data.items()}
    except (OSError, ValueError, TypeError):
        pass
    return {}


def save(data):
    tmp = KV_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, KV_PATH)


counts = load()


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, format, *args):
        pass

    def send_json(self, status, obj):
        body = json.dumps(obj).encode("utf-8")
        self.send_response(status)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(body)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def drain(self):
        length = self.headers.get("content-length")
        if length:
            try:
                n = int(length)
                if n > 0:
                    self.rfile.read(n)
            except ValueError:
                pass

    def route(self):
        self.drain()
        method = self.command
        path = self.path
        if method == "POST" and path.startswith("/hit/"):
            name = path[len("/hit/"):]
            if not NAME_RE.fullmatch(name):
                return self.send_json(400, {"error": "bad name"})
            with lock:
                counts[name] = counts.get(name, 0) + 1
                n = counts[name]
                save(counts)
            return self.send_json(200, {"name": name, "count": n})
        if method == "GET" and path.startswith("/count/"):
            name = path[len("/count/"):]
            if not NAME_RE.fullmatch(name):
                return self.send_json(400, {"error": "bad name"})
            with lock:
                n = counts.get(name, 0)
            return self.send_json(200, {"name": name, "count": n})
        if method == "GET" and path == "/top":
            with lock:
                items = [(k, v) for k, v in counts.items() if v > 0]
            items.sort(key=lambda kv: (-kv[1], kv[0].encode("utf-8")))
            return self.send_json(
                200, [{"name": k, "count": v} for k, v in items[:3]]
            )
        return self.send_json(404, {"error": "not found"})

    do_GET = route
    do_POST = route
    do_PUT = route
    do_DELETE = route
    do_PATCH = route
    do_HEAD = route
    do_OPTIONS = route
    do_TRACE = route
    do_CONNECT = route


def main():
    port = int(os.environ.get("PORT", "8000"))
    server = HTTPServer(("127.0.0.1", port), Handler)
    server.serve_forever()


if __name__ == "__main__":
    main()

import json
import os
import sys
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlsplit, parse_qs

STORE = os.environ.get("STORE", "store.json")


def load():
    try:
        with open(STORE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict) and "next" in data and "todos" in data:
            return data
    except Exception:
        pass
    return {"next": 1, "todos": {}}


def save(data):
    tmp = STORE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, STORE)


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send_json(self, code, obj):
        body = json.dumps(obj).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def send_empty(self, code):
        self.send_response(code)
        self.send_header("Content-Length", "0")
        self.end_headers()

    def not_found(self):
        self.send_json(404, {"error": "not found"})

    def read_body(self):
        try:
            n = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            n = 0
        raw = self.rfile.read(n) if n > 0 else b""
        try:
            return True, json.loads(raw.decode("utf-8"))
        except Exception:
            return False, None

    def dispatch(self):
        method = self.command
        parts = urlsplit(self.path)
        path = parts.path
        query = parse_qs(parts.query)
        # Always consume body to keep connection sane
        ok, body = (False, None)
        if method in ("POST", "PATCH", "PUT", "DELETE", "GET"):
            ok, body = self.read_body()

        if path == "/todos":
            if method == "GET":
                data = load()
                todos = sorted(data["todos"].values(), key=lambda t: t["id"])
                vals = query.get("done")
                if vals:
                    v = vals[-1]
                    if v == "true":
                        todos = [t for t in todos if t["done"] is True]
                    elif v == "false":
                        todos = [t for t in todos if t["done"] is False]
                return self.send_json(200, todos)
            if method == "POST":
                if not ok or not isinstance(body, dict):
                    return self.send_json(400, {"error": "title required"})
                title = body.get("title")
                if not isinstance(title, str) or not title.strip():
                    return self.send_json(400, {"error": "title required"})
                data = load()
                tid = data["next"]
                todo = {"id": tid, "title": title.strip(), "done": False}
                data["todos"][str(tid)] = todo
                data["next"] = tid + 1
                save(data)
                return self.send_json(201, todo)
            return self.not_found()

        if path.startswith("/todos/"):
            sid = path[len("/todos/"):]
            if not sid or not sid.isascii() or not sid.isdigit():
                return self.not_found()
            key = str(int(sid))
            data = load()
            todo = data["todos"].get(key)
            if todo is None:
                return self.not_found()
            if method == "GET":
                return self.send_json(200, todo)
            if method == "DELETE":
                del data["todos"][key]
                save(data)
                return self.send_empty(204)
            if method == "PATCH":
                if not ok or not isinstance(body, dict):
                    return self.send_json(400, {"error": "bad update"})
                upd = {}
                if "title" in body:
                    t = body["title"]
                    if not isinstance(t, str) or not t.strip():
                        return self.send_json(400, {"error": "bad update"})
                    upd["title"] = t.strip()
                if "done" in body:
                    d = body["done"]
                    if not isinstance(d, bool):
                        return self.send_json(400, {"error": "bad update"})
                    upd["done"] = d
                todo.update(upd)
                data["todos"][key] = todo
                save(data)
                return self.send_json(200, todo)
            return self.not_found()

        return self.not_found()

    def handle_one_request(self):
        try:
            self.raw_requestline = self.rfile.readline(65537)
            if len(self.raw_requestline) > 65536:
                self.send_error(414)
                return
            if not self.raw_requestline:
                self.close_connection = True
                return
            if not self.parse_request():
                return
            try:
                self.dispatch()
            except Exception:
                try:
                    self.send_json(500, {"error": "internal"})
                except Exception:
                    pass
            self.wfile.flush()
        except (TimeoutError, ConnectionError):
            self.close_connection = True


def main():
    port = int(os.environ.get("PORT", "8080"))
    server = HTTPServer(("127.0.0.1", port), Handler)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass


if __name__ == "__main__":
    main()

import json
import os
import re
import sqlite3
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

DB_PATH = os.environ["DB"]
PORT = int(os.environ.get("PORT", "8000"))

conn = sqlite3.connect(DB_PATH, check_same_thread=False, isolation_level=None)
conn.execute(
    "CREATE TABLE IF NOT EXISTS notes ("
    "id INTEGER PRIMARY KEY AUTOINCREMENT, "
    "title TEXT NOT NULL, body TEXT NOT NULL, tags TEXT NOT NULL)"
)
lock = threading.Lock()

ID_RE = re.compile(r"^/notes/([0-9]+)$")
VAL_RE = re.compile(r"^[A-Za-z0-9-]*$")


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send_json(self, code, obj):
        data = json.dumps(obj).encode("utf-8")
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(data)

    def read_body(self):
        n = self.headers.get("content-length")
        try:
            n = int(n) if n else 0
        except ValueError:
            n = 0
        return self.rfile.read(n) if n > 0 else b""

    def not_found(self):
        self.send_json(404, {"error": "not found"})

    def dispatch(self):
        raw = self.read_body()
        try:
            parts = urlsplit(self.path)
        except Exception:
            return self.not_found()
        path = parts.path
        m = self.command
        try:
            if path == "/notes":
                if m == "POST":
                    return self.create(raw)
                if m == "GET":
                    return self.list_notes(parts.query)
                return self.not_found()
            mm = ID_RE.match(path)
            if mm:
                nid = int(mm.group(1))
                if m == "GET":
                    return self.get_note(nid)
                if m == "DELETE":
                    return self.delete_note(nid)
            return self.not_found()
        except Exception:
            return self.not_found()

    def create(self, raw):
        try:
            data = json.loads(raw.decode("utf-8"))
        except Exception:
            data = None
        ok = isinstance(data, dict)
        if ok:
            title = data.get("title")
            body = data.get("body")
            tags = data.get("tags", [])
            ok = (
                isinstance(title, str) and title != ""
                and isinstance(body, str)
                and isinstance(tags, list)
                and all(isinstance(t, str) for t in tags)
            )
        if not ok:
            return self.send_json(400, {"error": "invalid note"})
        seen = []
        for t in tags:
            t = t.lower()
            if t not in seen:
                seen.append(t)
        with lock:
            cur = conn.execute(
                "INSERT INTO notes (title, body, tags) VALUES (?, ?, ?)",
                (title, body, json.dumps(seen)),
            )
            nid = cur.lastrowid
        self.send_json(201, {"id": nid})

    def get_note(self, nid):
        with lock:
            row = conn.execute(
                "SELECT id, title, body, tags FROM notes WHERE id = ?", (nid,)
            ).fetchone()
        if not row:
            return self.not_found()
        self.send_json(
            200,
            {"id": row[0], "title": row[1], "body": row[2], "tags": json.loads(row[3])},
        )

    def delete_note(self, nid):
        with lock:
            cur = conn.execute("DELETE FROM notes WHERE id = ?", (nid,))
            n = cur.rowcount
        if n <= 0:
            return self.not_found()
        self.send_json(200, {"deleted": nid})

    def list_notes(self, query):
        qs = parse_qs(query, keep_blank_values=True) if query else {}
        tag = None
        word = None
        if "tag" in qs:
            tag = qs["tag"][-1]
            if not VAL_RE.match(tag):
                return self.not_found()
            tag = tag.lower()
        if "q" in qs:
            word = qs["q"][-1]
            if not VAL_RE.match(word):
                return self.not_found()
        with lock:
            rows = conn.execute(
                "SELECT id, title, body, tags FROM notes ORDER BY id DESC"
            ).fetchall()
        out = []
        for r in rows:
            if tag is not None and tag not in json.loads(r[3]):
                continue
            if word is not None and word not in r[1] and word not in r[2]:
                continue
            out.append({"id": r[0], "title": r[1]})
        self.send_json(200, out)

    do_GET = dispatch
    do_POST = dispatch
    do_DELETE = dispatch
    do_PUT = dispatch
    do_PATCH = dispatch
    do_HEAD = dispatch
    do_OPTIONS = dispatch
    do_TRACE = dispatch
    do_CONNECT = dispatch


def main():
    server = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    server.daemon_threads = True
    server.serve_forever()


if __name__ == "__main__":
    main()

import os
import json
from collections import OrderedDict


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["CACHE"]

    with open(os.path.join(input_dir, "ops.txt"), "r", encoding="utf-8", newline="") as f:
        text = f.read()

    lines = text.split("\n")
    lines = [l[:-1] if l.endswith("\r") else l for l in lines]

    state = None
    if os.path.exists(kv_path):
        try:
            with open(kv_path, "r", encoding="utf-8") as f:
                state = json.load(f)
        except Exception:
            state = None
    if not isinstance(state, dict):
        state = {"items": [], "hits": 0, "misses": 0, "evictions": 0}

    cache = OrderedDict()  # LRU first, MRU last
    for k, v in state.get("items", []):
        cache[k] = v
    hits = int(state.get("hits", 0))
    misses = int(state.get("misses", 0))
    evictions = int(state.get("evictions", 0))

    out = []

    first = lines[0].strip() if lines else ""
    parts = first.split()
    capacity = 1
    if len(parts) == 2 and parts[0] == "capacity":
        try:
            capacity = int(parts[1])
        except ValueError:
            capacity = 1
    if capacity < 1:
        capacity = 1

    while len(cache) > capacity:
        k, _ = cache.popitem(last=False)
        evictions += 1
        out.append("evict " + k)

    for idx in range(1, len(lines)):
        lineno = idx + 1
        line = lines[idx]
        if line.strip() == "":
            continue
        ok = False
        if line.startswith("put "):
            rest = line[4:]
            sp = rest.find(" ")
            if sp > 0:
                key = rest[:sp]
                value = rest[sp + 1:]
                if key and value:
                    ok = True
                    if key in cache:
                        cache[key] = value
                        cache.move_to_end(key)
                    else:
                        if len(cache) >= capacity:
                            ek, _ = cache.popitem(last=False)
                            evictions += 1
                            out.append("evict " + ek)
                        cache[key] = value
        else:
            p = line.split(" ")
            if len(p) == 2 and p[1] != "":
                op, key = p
                if op == "get":
                    ok = True
                    if key in cache:
                        hits += 1
                        cache.move_to_end(key)
                        out.append(key + "=" + cache[key])
                    else:
                        misses += 1
                        out.append(key + " miss")
                elif op == "del":
                    ok = True
                    if key in cache:
                        del cache[key]
        if not ok:
            out.append("bad line %d" % lineno)

    keys = list(reversed(list(cache.keys())))
    out.append("cache: " + ",".join(keys) if keys else "cache:")
    out.append("stats hits %d misses %d evictions %d" % (hits, misses, evictions))

    new_state = {
        "items": [[k, v] for k, v in cache.items()],
        "hits": hits,
        "misses": misses,
        "evictions": evictions,
    }
    tmp = kv_path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(new_state, f, ensure_ascii=False)
    os.replace(tmp, kv_path)

    import sys
    sys.stdout.buffer.write(("\n".join(out) + "\n").encode("utf-8"))


if __name__ == "__main__":
    main()

import os
import sys
import json


def main():
    base = os.environ.get("INPUT", ".")
    path = os.path.join(base, "packages.json")
    try:
        with open(path, "rb") as f:
            raw = f.read()
        data = json.loads(raw.decode("utf-8"))
    except Exception:
        data = None
    if not isinstance(data, dict):
        print("error: not an object")
        return

    valid = {}
    invalid = []
    for name, val in data.items():
        if isinstance(val, list) and all(isinstance(x, str) for x in val):
            seen = []
            s = set()
            for x in val:
                if x not in s:
                    s.add(x)
                    seen.append(x)
            valid[name] = seen
        else:
            invalid.append(name)

    # missing deps
    missing = {}
    has_missing = set()
    for p, deps in valid.items():
        for d in deps:
            if d not in valid:
                missing.setdefault(d, set()).add(p)
                has_missing.add(p)

    # edges among valid packages
    edges = {p: [d for d in deps if d in valid] for p, deps in valid.items()}

    # Kahn-style build
    rev = {p: [] for p in valid}
    count = {}
    for p, ds in edges.items():
        count[p] = len(ds)
        for d in ds:
            rev[d].append(p)
    stage = {}
    queue = [p for p in valid if count[p] == 0 and p not in has_missing]
    i = 0
    while i < len(queue):
        p = queue[i]
        i += 1
        st = 1
        for d in edges[p]:
            st = max(st, stage[d] + 1)
        stage[p] = st
        for q in rev[p]:
            count[q] -= 1
            if count[q] == 0 and q not in has_missing:
                queue.append(q)

    # Tarjan SCC iterative
    index = {}
    low = {}
    onstack = set()
    stack = []
    sccs = []
    idx = 0
    for root in valid:
        if root in index:
            continue
        work = [(root, 0)]
        index[root] = low[root] = idx
        idx += 1
        stack.append(root)
        onstack.add(root)
        while work:
            v, pi = work[-1]
            ds = edges[v]
            if pi < len(ds):
                work[-1] = (v, pi + 1)
                w = ds[pi]
                if w not in index:
                    index[w] = low[w] = idx
                    idx += 1
                    stack.append(w)
                    onstack.add(w)
                    work.append((w, 0))
                elif w in onstack:
                    if index[w] < low[v]:
                        low[v] = index[w]
            else:
                work.pop()
                if work:
                    u = work[-1][0]
                    if low[v] < low[u]:
                        low[u] = low[v]
                if low[v] == index[v]:
                    comp = []
                    while True:
                        w = stack.pop()
                        onstack.discard(w)
                        comp.append(w)
                        if w == v:
                            break
                    sccs.append(comp)

    cycles = []
    in_cycle = set()
    for comp in sccs:
        if len(comp) >= 2 or (comp[0] in edges[comp[0]]):
            c = sorted(comp)
            cycles.append(c)
            in_cycle.update(c)
    cycles.sort(key=lambda c: c[0])

    out = []
    by_stage = {}
    for p, s in stage.items():
        by_stage.setdefault(s, []).append(p)
    for s in sorted(by_stage):
        out.append("stage %d: %s" % (s, ", ".join(sorted(by_stage[s]))))
    for c in cycles:
        out.append("cycle: " + ", ".join(c))
    for m in sorted(missing):
        out.append("missing: %s (needed by %s)" % (m, ", ".join(sorted(missing[m]))))
    if invalid:
        out.append("invalid: " + ", ".join(sorted(invalid)))
    blocked = sorted(p for p in valid if p not in stage and p not in in_cycle)
    if blocked:
        out.append("blocked: " + ", ".join(blocked))
    out.append("built %d of %d" % (len(stage), len(valid)))
    sys.stdout.write("\n".join(out) + "\n")


main()

import os
import re

TIME_RE = re.compile(r'^(\d\d):(\d\d)$')


def parse_time(s, allow_24=False):
    m = TIME_RE.match(s)
    if not m:
        return None
    h, mi = int(m.group(1)), int(m.group(2))
    if allow_24 and h == 24 and mi == 0:
        return 1440
    if 0 <= h <= 23 and 0 <= mi <= 59:
        return h * 60 + mi
    return None


def fmt(t):
    return "%02d:%02d" % (t // 60, t % 60)


def main():
    d = os.environ["INPUT"]
    with open(os.path.join(d, "bookings.csv"), "r", encoding="utf-8",
              errors="surrogateescape", newline="") as f:
        data = f.read()
    lines = data.split("\n")
    skipped = []
    seen = set()
    groups = {}
    for idx, raw in enumerate(lines):
        lineno = idx + 1
        if lineno == 1:
            continue
        line = raw.rstrip("\r")
        if line.strip() == "":
            continue
        fields = line.split(",")
        if len(fields) != 5:
            skipped.append(lineno)
            continue
        room, day, st, en, who = fields
        s = parse_time(st)
        e = parse_time(en, allow_24=True)
        if s is None or e is None or e <= s:
            skipped.append(lineno)
            continue
        key = tuple(fields)
        if key in seen:
            continue
        seen.add(key)
        groups.setdefault((room, day), []).append((s, e, who))

    out = []
    for (room, day) in sorted(groups):
        bs = groups[(room, day)]
        out.append("%s %s" % (room, day))
        ivs = sorted((s, e) for s, e, _ in bs)
        merged = []
        for s, e in ivs:
            if merged and s <= merged[-1][1]:
                if e > merged[-1][1]:
                    merged[-1][1] = e
            else:
                merged.append([s, e])
        out.append("  busy " + ", ".join("%s-%s" % (fmt(s), fmt(e)) for s, e in merged))
        free = []
        cur = 540
        for s, e in merged:
            if e <= cur:
                continue
            if s >= 1080:
                break
            if s > cur:
                free.append((cur, min(s, 1080)))
            cur = max(cur, e)
            if cur >= 1080:
                break
        if cur < 1080:
            free.append((cur, 1080))
        free = [(s, e) for s, e in free if e - s >= 30]
        if free:
            out.append("  free " + ", ".join("%s-%s" % (fmt(s), fmt(e)) for s, e in free))
        else:
            out.append("  free none")
        conf = []
        n = len(bs)
        for i in range(n):
            for j in range(i + 1, n):
                s = max(bs[i][0], bs[j][0])
                e = min(bs[i][1], bs[j][1])
                if e - s >= 1:
                    names = sorted([bs[i][2], bs[j][2]])
                    text = "  conflict %s/%s %s-%s" % (names[0], names[1], fmt(s), fmt(e))
                    conf.append((s, text))
        conf.sort()
        for _, text in conf:
            out.append(text)
    if skipped:
        out.append("skipped: " + ", ".join(str(x) for x in skipped))
    else:
        out.append("skipped: none")
    print("\n".join(out))


