    main()

import json
import os
import sys
from decimal import Decimal


def _reject_constant(name):
    raise ValueError("invalid constant " + name)


def parse_json(text):
    return json.loads(text, parse_float=Decimal, parse_constant=_reject_constant)


def type_of(v):
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "boolean"
    if isinstance(v, int):
        return "integer"
    if isinstance(v, Decimal):
        return "number"
    if isinstance(v, str):
        return "string"
    if isinstance(v, list):
        return "array"
    if isinstance(v, dict):
        return "object"
    return "unknown"


def matches(t, v):
    actual = type_of(v)
    if t == "number":
        return actual in ("integer", "number")
    return actual == t


def validate(schema, value, path, errors):
    t = schema.get("type")
    if not matches(t, value):
        errors.append((path, "expected " + str(t)))
        return
    if t == "object":
        props = schema.get("properties") or {}
        required = schema.get("required") or []
        seen = set()
        for name in required:
            if name in seen:
                continue
            seen.add(name)
            if name not in value:
                errors.append((path + "." + name, "missing required field"))
        additional = schema.get("additional", True)
        for name, v in value.items():
            if name in props:
                validate(props[name], v, path + "." + name, errors)
            elif additional is False:
                errors.append((path + "." + name, "unexpected field"))
    elif t == "array":
        mi = schema.get("min_items")
        if mi is not None and len(value) < mi:
            errors.append((path, "fewer than %d items" % mi))
        items = schema.get("items")
        if items is not None:
            for i, v in enumerate(value):
                validate(items, v, "%s[%d]" % (path, i), errors)
    elif t == "string":
        n = len(value)
        mn = schema.get("min_length")
        mx = schema.get("max_length")
        enum = schema.get("enum")
        if mn is not None and n < mn:
            errors.append((path, "shorter than %d" % mn))
        elif mx is not None and n > mx:
            errors.append((path, "longer than %d" % mx))
        elif enum is not None and value not in enum:
            errors.append((path, "not in enum"))
    elif t in ("integer", "number"):
        mn = schema.get("minimum")
        mx = schema.get("maximum")
        if mn is not None and value < mn:
            errors.append((path, "less than %s" % mn))
        elif mx is not None and value > mx:
            errors.append((path, "greater than %s" % mx))


def main():
    base = os.environ["INPUT"]
    with open(os.path.join(base, "schema.json"), "rb") as f:
        schema = parse_json(f.read().decode("utf-8"))
    with open(os.path.join(base, "records.jsonl"), "rb") as f:
        data = f.read()

    lines = data.split(b"\n")
    if lines and lines[-1] == b"":
        lines.pop()

    out = []
    valid = 0
    total = 0
    for idx, raw in enumerate(lines, 1):
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            text = None
        if text is not None and text.strip() == "":
            continue
        if text is None and raw.strip() == b"":
            continue
        total += 1
        if text is None:
            out.append("line %d: invalid JSON" % idx)
            continue
        try:
            value = parse_json(text)
        except (ValueError, RecursionError):
            out.append("line %d: invalid JSON" % idx)
            continue
        errors = []
        validate(schema, value, "$", errors)
        if not errors:
            valid += 1
            out.append("line %d: ok" % idx)
        else:
            errors.sort(key=lambda e: (e[0].encode("utf-8", "surrogatepass"),
                                       e[1].encode("utf-8", "surrogatepass")))
            for p, m in errors:
                out.append("line %d: %s: %s" % (idx, p, m))
    out.append("valid %d of %d" % (valid, total))
    sys.stdout.buffer.write(("\n".join(out) + "\n").encode("utf-8", "surrogatepass"))


if __name__ == "__main__":
    sys.setrecursionlimit(10000)
    main()

import json
import os
import sys
import urllib.request
import urllib.error
import urllib.parse


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


OPENER = urllib.request.build_opener(NoRedirect)


def load_state(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            return {k: v for k, v in data.items() if isinstance(v, int) and not isinstance(v, bool)}
    except Exception:
        pass
    return {}


def save_state(path, state):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(state, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)


def put(base, rid, body):
    url = base.rstrip("/") + "/records/" + urllib.parse.quote(rid, safe="")
    req = urllib.request.Request(
        url, data=body, method="PUT",
        headers={"content-type": "application/json"},
    )
    try:
        with OPENER.open(req, timeout=30) as resp:
            resp.read()
            return resp.status
    except urllib.error.HTTPError as e:
        try:
            e.read()
        except Exception:
            pass
        return e.code
    except Exception:
        return None


def main():
    in_dir = os.environ["INPUT"]
    state_path = os.environ["STATE"]
    base = os.environ["API"]

    with open(os.path.join(in_dir, "records.jsonl"), "rb") as f:
        raw = f.read()
    text = raw.decode("utf-8", errors="replace")
    lines = text.split("\n")

    out = []
    records = {}
    for i, line in enumerate(lines, 1):
        if line.strip() == "":
            continue
        ok = False
        try:
            obj = json.loads(line)
            if (isinstance(obj, dict)
                    and isinstance(obj.get("id"), str)
                    and isinstance(obj.get("version"), int)
                    and not isinstance(obj.get("version"), bool)):
                ok = True
        except Exception:
            ok = False
        if not ok:
            out.append("line %d invalid" % i)
            continue
        records[obj["id"]] = obj

    state = load_state(state_path)
    results = {}
    counts = {"synced": 0, "unchanged": 0, "rejected": 0, "failed": 0}

    for rid in sorted(records, key=lambda s: s.encode("utf-8", "surrogatepass")):
        rec = records[rid]
        last = state.get(rid)
        if last is not None and not rec["version"] > last:
            results[rid] = "%s unchanged" % rid
            counts["unchanged"] += 1
            continue
        body = json.dumps(rec).encode("utf-8")
        outcome = None
        for _ in range(3):
            st = put(base, rid, body)
            if st is not None and 200 <= st < 300:
                outcome = "synced"
                break
            if st is not None and 400 <= st < 500:
                outcome = ("rejected", st)
                break
        if outcome == "synced":
            state[rid] = rec["version"]
            save_state(state_path, state)
            results[rid] = "%s synced" % rid
            counts["synced"] += 1
        elif isinstance(outcome, tuple):
            results[rid] = "%s rejected %d" % (rid, outcome[1])
            counts["rejected"] += 1
        else:
            results[rid] = "%s failed" % rid
            counts["failed"] += 1

    for rid in sorted(results, key=lambda s: s.encode("utf-8", "surrogatepass")):
        out.append(results[rid])
    out.append("synced %d unchanged %d rejected %d failed %d" % (
        counts["synced"], counts["unchanged"], counts["rejected"], counts["failed"]))

    save_state(state_path, state)
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

import os
import re
import sqlite3
import datetime

MAX = 9223372036854775807
INT_RE = re.compile(r'^[+-]?[0-9]+$')


def fmt_time(ms):
    secs = ms // 1000
    dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc) + datetime.timedelta(seconds=secs)
    return dt.strftime('%Y-%m-%dT%H:%M:%SZ')


def parse_int(s):
    if not INT_RE.match(s):
        return None
    return int(s)


def main():
    input_dir = os.environ['INPUT']
    db_path = os.environ['DB']
    log_path = os.environ['LOG']
    now_ms = int(os.environ['CLOCK'].strip())
    now_s = fmt_time(now_ms)

    conn = sqlite3.connect(db_path, isolation_level=None)
    conn.execute('CREATE TABLE IF NOT EXISTS accounts ('
                 'name TEXT PRIMARY KEY, balance TEXT NOT NULL, '
                 'closed INTEGER NOT NULL DEFAULT 0, last INTEGER NOT NULL)')
    conn.execute('CREATE TABLE IF NOT EXISTS transfers ('
                 'id TEXT PRIMARY KEY, frm TEXT NOT NULL, dst TEXT NOT NULL, cents TEXT NOT NULL)')

    with open(os.path.join(input_dir, 'ops.txt'), 'rb') as f:
        data = f.read().decode('utf-8', errors='surrogateescape')
    lines = data.split('\n')

    ok = failed = dup = 0
    log_lines = []

    def get_acct(name):
        return conn.execute('SELECT balance, closed FROM accounts WHERE name=?', (name,)).fetchone()

    def process(words):
        op = words[0]
        if op == 'open':
            if len(words) != 3:
                return 'malformed'
            amt = parse_int(words[2])
            if amt is None:
                return 'malformed'
            if amt < 0:
                return 'bad amount'
            name = words[1]
            if get_acct(name) is not None:
                return 'account exists'
            conn.execute('INSERT INTO accounts(name, balance, closed, last) VALUES (?,?,0,?)',
                         (name, str(amt), now_ms))
            return None
        elif op == 'transfer':
            if len(words) != 5:
                return 'malformed'
            amt = parse_int(words[4])
            if amt is None:
                return 'malformed'
            tid, frm, dst = words[1], words[2], words[3]
            row = conn.execute('SELECT frm, dst, cents FROM transfers WHERE id=?', (tid,)).fetchone()
            if row is not None:
                if row[0] == frm and row[1] == dst and int(row[2]) == amt:
                    return 'DUP'
                return 'id reused'
            if amt <= 0:
                return 'bad amount'
            if frm == dst:
                return 'same account'
            a = get_acct(frm)
            if a is None or a[1]:
                return 'no account ' + frm
            b = get_acct(dst)
            if b is None or b[1]:
                return 'no account ' + dst
            fb = int(a[0])
            tb = int(b[0])
            if fb < amt:
                return 'insufficient funds'
            if tb + amt > MAX:
                return 'overflow'
            conn.execute('UPDATE accounts SET balance=?, last=? WHERE name=?', (str(fb - amt), now_ms, frm))
            conn.execute('UPDATE accounts SET balance=?, last=? WHERE name=?', (str(tb + amt), now_ms, dst))
            conn.execute('INSERT INTO transfers(id, frm, dst, cents) VALUES (?,?,?,?)',
                         (tid, frm, dst, str(amt)))
            return None
        elif op == 'close':
            if len(words) != 2:
                return 'malformed'
            name = words[1]
            a = get_acct(name)
            if a is None or a[1]:
                return 'no account ' + name
            if int(a[0]) != 0:
                return 'balance not zero'
            conn.execute('UPDATE accounts SET closed=1 WHERE name=?', (name,))
            return None
        else:
            return 'malformed'

    for idx, raw in enumerate(lines, start=1):
        line = raw.rstrip('\r')
        if line.strip() == '':
            continue
        words = line.split()
        conn.execute('BEGIN IMMEDIATE')
        try:
            res = process(words)
            if res is None:
                conn.execute('COMMIT')
            else:
                conn.execute('ROLLBACK')
        except Exception:
            conn.execute('ROLLBACK')
            raise
        if res is None:
            ok += 1
        elif res == 'DUP':
            dup += 1
        else:
            failed += 1
            log_lines.append('%s line %d: %s\n' % (now_s, idx, res))
            with open(log_path, 'a', encoding='utf-8', errors='surrogateescape') as lf:
                lf.write(log_lines[-1])

    out = ['ok %d failed %d duplicate %d' % (ok, failed, dup)]
    rows = conn.execute('SELECT name, balance, last FROM accounts WHERE closed=0').fetchall()
    rows.sort(key=lambda r: r[0].encode('utf-8', errors='surrogateescape'))
    for name, bal, last in rows:
        out.append('%s %s last %s' % (name, bal, fmt_time(int(last))))
    conn.close()
    print('\n'.join(out))


if __name__ == '__main__':
    main()

import os
import re
import json
import hmac
import hashlib
import secrets
from http.server import HTTPServer, BaseHTTPRequestHandler

KV_PATH = os.environ.get("STORE", "store.json")
NOW = int(os.environ.get("CLOCK", "0"))
PORT = int(os.environ.get("PORT", "8080"))

SESSION_MS = 30 * 60 * 1000
LOCK_MS = 15 * 60 * 1000
NAME_RE = re.compile(r"^[a-z0-9_]{3,20}$")


def load():
    try:
        with open(KV_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            raise ValueError
    except Exception:
        data = {}
    data.setdefault("users", {})
    data.setdefault("sessions", {})
    return data


STATE = load()


def save():
    tmp = KV_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(STATE, f)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, KV_PATH)


def hash_pw(salt, name, password):
    return hashlib.pbkdf2_hmac(
        "sha256", (name + ":" + password).encode("utf-8"), bytes.fromhex(salt), 100000
    ).hex()


def parse_creds(body):
    try:
        obj = json.loads(body.decode("utf-8"))
    except Exception:
        return None
    if not isinstance(obj, dict):
        return None
    name = obj.get("name")
    pw = obj.get("password")
    if not isinstance(name, str) or not isinstance(pw, str):
        return None
    return name, pw


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def send_json(self, code, obj=None):
        if code == 204:
            self.send_response(204)
            self.send_header("Content-Length", "0")
            self.end_headers()
            return
        data = json.dumps(obj).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def read_body(self):
        try:
            n = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            n = 0
        return self.rfile.read(n) if n > 0 else b""

    def session(self):
        auth = self.headers.get("Authorization")
        if not auth or not auth.startswith("Bearer "):
            return None, None
        token = auth[len("Bearer "):].strip()
        s = STATE["sessions"].get(token)
        if not s:
            return None, None
        if not NOW < s["expires"]:
            del STATE["sessions"][token]
            save()
            return None, None
        if s["name"] not in STATE["users"]:
            return None, None
        return token, s

    def handle_any(self):
        path = self.path.split("?", 1)[0]
        method = self.command
        body = self.read_body()
        try:
            if method == "POST" and path == "/users":
                return self.create_user(body)
            if method == "POST" and path == "/login":
                return self.login(body)
            if method == "GET" and path == "/me":
                return self.me()
            if method == "POST" and path == "/logout":
                return self.logout()
            self.send_json(404, {"error": "not found"})
        except Exception:
            try:
                self.send_json(500, {"error": "internal"})
            except Exception:
                pass

    def create_user(self, body):
        c = parse_creds(body)
        if c is None:
            return self.send_json(400, {"error": "invalid"})
        name, pw = c
        if not NAME_RE.match(name) or len(pw.encode("utf-8")) < 8:
            return self.send_json(400, {"error": "invalid"})
        if name in STATE["users"]:
            return self.send_json(409, {"error": "name taken"})
        salt = secrets.token_hex(16)
        STATE["users"][name] = {
            "salt": salt,
            "hash": hash_pw(salt, name, pw),
            "fails": 0,
            "locked_until": 0,
            "logins": 0,
        }
        save()
        self.send_json(201, {"name": name})

    def login(self, body):
        c = parse_creds(body)
        if c is None:
            return self.send_json(401, {"error": "bad credentials"})
        name, pw = c
        u = STATE["users"].get(name)
        if u is None:
            return self.send_json(401, {"error": "bad credentials"})
        if NOW < u.get("locked_until", 0):
            return self.send_json(429, {"error": "locked"})
        if u.get("locked_until", 0):
            u["locked_until"] = 0
            u["fails"] = 0
        if not hmac.compare_digest(hash_pw(u["salt"], name, pw), u["hash"]):
            u["fails"] = u.get("fails", 0) + 1
            if u["fails"] >= 3:
                u["locked_until"] = NOW + LOCK_MS
                u["fails"] = 0
            save()
            return self.send_json(401, {"error": "bad credentials"})
        u["fails"] = 0
        u["logins"] = u.get("logins", 0) + 1
        token = secrets.token_bytes(16).hex()
        STATE["sessions"][token] = {"name": name, "expires": NOW + SESSION_MS}
        save()
        self.send_json(200, {"token": token, "expires_in": 1800})

    def me(self):
        token, s = self.session()
        if s is None:
            return self.send_json(401, {"error": "unauthorized"})
        s["expires"] = NOW + SESSION_MS
        save()
        u = STATE["users"][s["name"]]
        self.send_json(200, {"name": s["name"], "logins": u.get("logins", 0)})

    def logout(self):
        token, s = self.session()
        if s is None:
            return self.send_json(401, {"error": "unauthorized"})
        del STATE["sessions"][token]
        save()
        self.send_json(204)

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = do_HEAD = do_OPTIONS = handle_any


def main():
    server = HTTPServer(("127.0.0.1", PORT), Handler)
    server.serve_forever()


if __name__ == "__main__":
    main()

import json
import os
import sqlite3
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit, parse_qs

DB_PATH = os.environ["DB"]
LOCK = threading.Lock()
CONN = sqlite3.connect(DB_PATH, check_same_thread=False, isolation_level=None)
CONN.execute("PRAGMA journal_mode=WAL")
CONN.execute("""CREATE TABLE IF NOT EXISTS payments (
    seq INTEGER PRIMARY KEY AUTOINCREMENT,
    account TEXT NOT NULL,
    cents INTEGER NOT NULL,
    currency TEXT NOT NULL,
    status TEXT NOT NULL,
    refunded INTEGER NOT NULL)""")
CONN.execute("""CREATE TABLE IF NOT EXISTS idem (
    k TEXT PRIMARY KEY,
    method TEXT NOT NULL,
    path TEXT NOT NULL,
    body TEXT NOT NULL,
    status INTEGER NOT NULL,
    resp TEXT NOT NULL)""")


def is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def pay_json(row):
    seq, account, cents, currency, status, refunded = row
    return {"id": "pay_%d" % seq, "account": account, "cents": cents,
            "currency": currency, "status": status, "refunded": refunded}


def get_payment(pid):
    if not pid.startswith("pay_"):
        return None
    n = pid[4:]
    if not n.isdigit() or str(int(n)) != n:
        return None
    return CONN.execute(
        "SELECT seq, account, cents, currency, status, refunded FROM payments WHERE seq=?",
        (int(n),)).fetchone()


def err(status, msg):
    return status, {"error": msg}


def parse_json(raw):
    try:
        return True, json.loads(raw.decode("utf-8"))
    except Exception:
        return False, None


def canon(raw):
    ok, v = parse_json(raw)
    if ok:
        return "j:" + json.dumps(v, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    return "r:" + raw.decode("utf-8", "replace")


def create_payment(raw):
    ok, b = parse_json(raw)
    if not ok or not isinstance(b, dict) or set(b.keys()) != {"account", "cents", "currency"}:
        return err(422, "invalid payment")
    a, c, cur = b["account"], b["cents"], b["currency"]
    if not isinstance(a, str) or a == "" or not is_int(c) or c <= 0 or cur not in ("EUR", "USD"):
        return err(422, "invalid payment")
    cur_ = CONN.execute(
        "INSERT INTO payments (account, cents, currency, status, refunded) VALUES (?,?,?,?,0)",
        (a, c, cur, "pending"))
    row = CONN.execute(
        "SELECT seq, account, cents, currency, status, refunded FROM payments WHERE seq=?",
        (cur_.lastrowid,)).fetchone()
    return 201, pay_json(row)


def refund(pid, raw):
    row = get_payment(pid)
    if row is None:
        return err(404, "not found")
    ok, b = parse_json(raw)
    if not ok or not isinstance(b, dict) or "cents" not in b or not is_int(b["cents"]) or b["cents"] <= 0:
        return err(422, "invalid refund")
    n = b["cents"]
    seq, account, cents, currency, status, refunded = row
    if status != "captured":
        return err(409, "invalid transition")
    if refunded + n > cents:
        return err(409, "exceeds captured")
    refunded += n
    if refunded == cents:
        status = "refunded"
    CONN.execute("UPDATE payments SET refunded=?, status=? WHERE seq=?", (refunded, status, seq))
    return 200, pay_json((seq, account, cents, currency, status, refunded))


def transition(pid, action):
    row = get_payment(pid)
    if row is None:
        return err(404, "not found")
    seq, account, cents, currency, status, refunded = row
    if action == "capture":
        if status == "captured":
            return 200, pay_json(row)
        if status != "pending":
            return err(409, "invalid transition")
        new = "captured"
    else:
        if status != "pending":
            return err(409, "invalid transition")
        new = "canceled"
    CONN.execute("UPDATE payments SET status=? WHERE seq=?", (new, seq))
    return 200, pay_json((seq, account, cents, currency, new, refunded))


def handle(method, target, headers, raw):
    parts = urlsplit(target)
    path = parts.path
    segs = [s for s in path.split("/")]
    # segs[0] == "" for absolute path
    if method == "GET":
        if path == "/payments":
            qs = parse_qs(parts.query, keep_blank_values=True)
            if "account" not in qs:
                return err(404, "not found")
            acct = qs["account"][0]
            rows = CONN.execute(
                "SELECT seq, account, cents, currency, status, refunded FROM payments "
                "WHERE account=? ORDER BY seq", (acct,)).fetchall()
            return 200, [pay_json(r) for r in rows]
        if len(segs) == 3 and segs[1] == "payments" and segs[2]:
            row = get_payment(segs[2])
            if row is None:
                return err(404, "not found")
            return 200, pay_json(row)
        return err(404, "not found")
    if method != "POST":
        return err(404, "not found")

    kind = None
    pid = None
    if path == "/payments":
        kind = "create"
    elif len(segs) == 4 and segs[1] == "payments" and segs[2] and segs[3] in ("capture", "cancel", "refund"):
        kind = segs[3]
        pid = segs[2]
    else:
        return err(404, "not found")

    if kind == "capture" or kind == "cancel":
        return transition(pid, kind)

    key = headers.get("idempotency-key")
    if key is None:
        return err(400, "missing idempotency key")
    body_c = canon(raw)
    existing = CONN.execute(
        "SELECT method, path, body, status, resp FROM idem WHERE k=?", (key,)).fetchone()
    if existing is not None:
        m, p, bc, st, resp = existing
        if m == method and p == path and bc == body_c:
            return st, ("raw", resp)
        return err(409, "key reused")
    if kind == "create":
        st, obj = create_payment(raw)
    else:
        st, obj = refund(pid, raw)
    if 200 <= st < 300:
        text = json.dumps(obj)
        CONN.execute("INSERT INTO idem (k, method, path, body, status, resp) VALUES (?,?,?,?,?,?)",
                     (key, method, path, body_c, st, text))
        return st, ("raw", text)
    return st, obj


class H(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *a):
        pass

    def _go(self):
        n = int(self.headers.get("content-length") or 0)
        raw = self.rfile.read(n) if n > 0 else b""
        hdrs = {k.lower(): v for k, v in self.headers.items()}
        with LOCK:
            try:
                CONN.execute("BEGIN IMMEDIATE")
                st, obj = handle(self.command, self.path, hdrs, raw)
                CONN.execute("COMMIT")
            except Exception:
                try:
                    CONN.execute("ROLLBACK")
                except Exception:
                    pass
                st, obj = 500, {"error": "internal"}
        if isinstance(obj, tuple) and obj[0] == "raw":
            text = obj[1]
        else:
            text = json.dumps(obj)
        data = text.encode("utf-8")
        self.send_response(st)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    do_GET = do_POST = do_PUT = do_DELETE = do_PATCH = do_HEAD = do_OPTIONS = _go


def main():
    srv = ThreadingHTTPServer(("127.0.0.1", int(os.environ["PORT"])), H)
    srv.daemon_threads = True
    srv.serve_forever()


if __name__ == "__main__":
    main()

import os
import sys
import json
import hashlib
import re

WORD_RE = re.compile(rb'[^\x00-\x2f\x3a-\x40\x5b-\x60\x7b-\x7f]+')


def words_of(data):
    out = set()
    for m in WORD_RE.findall(data):
        w = m.decode('utf-8', 'surrogateescape').lower()
        out.add(w)
    return out


def bkey(s):
    return s.encode('utf-8', 'surrogateescape')


def out(line):
    sys.stdout.buffer.write(bkey(line) + b'\n')


def main():
    docs = os.environ['DOCS']
    queries = os.environ['QUERIES']
    kvpath = os.environ['INDEX']

    state = {'files': {}, 'inv': {}}
    if os.path.exists(kvpath):
        try:
            with open(kvpath, 'r', encoding='utf-8') as f:
                state = json.load(f)
        except Exception:
            state = {'files': {}, 'inv': {}}
    files = state.get('files', {})
    inv = {w: set(ps) for w, ps in state.get('inv', {}).items()}

    current = {}
    dbytes = os.fsencode(docs)
    for root, dirs, fnames in os.walk(dbytes):
        for fn in fnames:
            full = os.path.join(root, fn)
            if not os.path.isfile(full):
                continue
            rel = os.path.relpath(full, dbytes).replace(os.sep.encode(), b'/')
            current[rel.decode('utf-8', 'surrogateescape')] = full

    events = []
    unchanged = 0

    def remove_words(path, wl):
        for w in wl:
            s = inv.get(w)
            if s is not None:
                s.discard(path)
                if not s:
                    del inv[w]

    def add_words(path, wl):
        for w in wl:
            inv.setdefault(w, set()).add(path)

    for path, full in current.items():
        try:
            with open(full, 'rb') as f:
                data = f.read()
        except OSError:
            continue
        h = hashlib.sha256(data).hexdigest()
        old = files.get(path)
        if old is not None and old['hash'] == h:
            unchanged += 1
            continue
        wl = sorted(words_of(data))
        if old is not None:
            remove_words(path, old['words'])
            events.append((path, 'changed'))
        else:
            events.append((path, 'added'))
        add_words(path, wl)
        files[path] = {'hash': h, 'words': wl}

    for path in list(files.keys()):
        if path not in current:
            remove_words(path, files[path]['words'])
            del files[path]
            events.append((path, 'removed'))

    events.sort(key=lambda e: bkey(e[0]))
    for path, kind in events:
        out('%s %s' % (kind, path))
    out('unchanged %d' % unchanged)

    newstate = {'files': files, 'inv': {w: sorted(ps) for w, ps in inv.items()}}
    tmp = kvpath + '.tmp'
    with open(tmp, 'w', encoding='utf-8') as f:
        json.dump(newstate, f)
    os.replace(tmp, kvpath)

    qpath = os.path.join(queries, 'queries.txt')
    try:
        with open(qpath, 'rb') as f:
            qdata = f.read()
    except OSError:
        qdata = b''
    for raw in qdata.split(b'\n'):
        if raw.endswith(b'\r'):
            raw = raw[:-1]
        if not raw.strip():
            continue
        line = raw.decode('utf-8', 'surrogateescape')
        qw = words_of(raw)
        result = None
        if qw:
            for w in qw:
                s = inv.get(w, set())
                result = set(s) if result is None else (result & s)
                if not result:
                    break
        if result:
            out('%s: %s' % (line, ', '.join(sorted(result, key=bkey))))
        else:
            out('%s: none' % line)
    sys.stdout.flush()


if __name__ == '__main__':
    main()

import json
import os
import sqlite3
import sys
import urllib.error
import urllib.parse
import urllib.request


def is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def valid_change(c):
    if not isinstance(c, dict):
        return False
    op = c.get("op")
    if op == "upsert":
        return (isinstance(c.get("sku"), str) and isinstance(c.get("name"), str)
                and is_int(c.get("qty")) and is_int(c.get("version")))
    if op == "delete":
        return isinstance(c.get("sku"), str) and is_int(c.get("version"))
    return False


def fetch(base, cursor):
    url = base.rstrip("/") + "/changes?cursor=" + urllib.parse.quote(str(cursor), safe="")
    try:
        with urllib.request.urlopen(url, timeout=30) as resp:
            status = resp.status
            body = resp.read()
    except urllib.error.HTTPError as e:
        return ("status", e.code)
    except Exception:
        return ("noresp", None)
    if status != 200:
        return ("status", status)
    try:
        data = json.loads(body.decode("utf-8"))
    except Exception:
        return ("invalid", None)
    if not isinstance(data, dict) or not isinstance(data.get("changes"), list):
        return ("invalid", None)
    nxt = data.get("next")
    if nxt is not None and not (isinstance(nxt, str) or is_int(nxt)):
        return ("invalid", None)
    return ("ok", data)


def main():
    base = os.environ["API"]
    conn = sqlite3.connect(os.environ["DB"], isolation_level=None)
    conn.execute("CREATE TABLE IF NOT EXISTS items (sku TEXT PRIMARY KEY, qty INTEGER NOT NULL, name TEXT NOT NULL)")
    conn.execute("CREATE TABLE IF NOT EXISTS versions (sku TEXT PRIMARY KEY, version INTEGER NOT NULL)")
    conn.execute("CREATE TABLE IF NOT EXISTS state (k TEXT PRIMARY KEY, v TEXT NOT NULL)")
    row = conn.execute("SELECT v FROM state WHERE k='cursor'").fetchone()
    cursor = row[0] if row else "0"

    pages = applied = stale = invalid = 0
    outcome = None
    while True:
        kind, data = fetch(base, cursor)
        if kind == "status":
            outcome = "stopped at %s (status %d)" % (cursor, data)
            break
        if kind == "noresp":
            outcome = "stopped at %s (no response)" % cursor
            break
        if kind == "invalid":
            outcome = "stopped at %s (invalid page)" % cursor
            break
        nxt = data.get("next")
        a = s = i = 0
        conn.execute("BEGIN IMMEDIATE")
        try:
            for c in data["changes"]:
                if not valid_change(c):
                    i += 1
                    continue
                sku = c["sku"]
                ver = c["version"]
                r = conn.execute("SELECT version FROM versions WHERE sku=?", (sku,)).fetchone()
                if r is not None and ver <= r[0]:
                    s += 1
                    continue
                conn.execute("INSERT OR REPLACE INTO versions (sku, version) VALUES (?, ?)", (sku, ver))
                if c["op"] == "upsert":
                    conn.execute("INSERT OR REPLACE INTO items (sku, qty, name) VALUES (?, ?, ?)",
                                 (sku, c["qty"], c["name"]))
                else:
                    conn.execute("DELETE FROM items WHERE sku=?", (sku,))
                a += 1
            new_cursor = cursor if nxt is None else str(nxt)
            conn.execute("INSERT OR REPLACE INTO state (k, v) VALUES ('cursor', ?)", (new_cursor,))
            conn.execute("COMMIT")
        except Exception:
            conn.execute("ROLLBACK")
            raise
        pages += 1
        applied += a
        stale += s
        invalid += i
        if nxt is None:
            outcome = "complete"
            break
        cursor = str(nxt)

    out = ["pages %d applied %d stale %d invalid %d" % (pages, applied, stale, invalid), outcome]
    items = conn.execute("SELECT sku, qty, name FROM items").fetchall()
    items.sort(key=lambda t: t[0].encode("utf-8", "surrogatepass"))
    for sku, qty, name in items:
        out.append("%s %d %s" % (sku, qty, name))
    conn.close()
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

import json
import os
import sys


def load_state(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict) and isinstance(data.get("jobs"), dict):
            return data
    except (OSError, ValueError):
        pass
    return {"jobs": {}}


def save_state(path, state):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(state, f)
    os.replace(tmp, path)


def main():
    input_dir = os.environ["INPUT"]
    kv_path = os.environ["QUEUE"]
    now = int(os.environ["CLOCK"])

    state = load_state(kv_path)
    jobs = state["jobs"]
    out = []

    # Enqueue
    enq_path = os.path.join(input_dir, "enqueue.jsonl")
    try:
        with open(enq_path, "r", encoding="utf-8") as f:
            content = f.read()
    except OSError:
        content = ""
    for n, line in enumerate(content.splitlines(), start=1):
        if not line.strip():
            continue
        try:
            obj = json.loads(line)
        except ValueError:
            obj = None
        if (
            not isinstance(obj, dict)
            or not isinstance(obj.get("id"), str)
            or not isinstance(obj.get("priority"), int)
            or isinstance(obj.get("priority"), bool)
        ):
            out.append("invalid line %d" % n)
            continue
        jid = obj["id"]
        if jid in jobs:
            out.append("duplicate %s" % jid)
            continue
        jobs[jid] = {
            "priority": obj["priority"],
            "due": now,
            "attempts": 0,
            "state": "pending",
        }

    # Script
    script = {}
    try:
        with open(os.path.join(input_dir, "script.json"), "r", encoding="utf-8") as f:
            s = json.load(f)
        if isinstance(s, dict):
            script = s
    except (OSError, ValueError):
        pass

    # Work
    due = [
        (jid, j)
        for jid, j in jobs.items()
        if j["state"] == "pending" and j["due"] <= now
    ]
    due.sort(key=lambda p: (-p[1]["priority"], p[1]["due"], p[0].encode("utf-8")))
    backoff = {1: 60, 2: 120, 3: 240}
    for jid, j in due[:5]:
        j["attempts"] += 1
        a = j["attempts"]
        outcomes = script.get(jid)
        if isinstance(outcomes, list) and outcomes:
            outcome = outcomes[min(a - 1, len(outcomes) - 1)]
        else:
            outcome = "ok"
        if outcome == "fail":
            if a >= 4:
                j["state"] = "dead"
                out.append("dead %s" % jid)
            else:
                secs = backoff[a]
                j["due"] = now + secs * 1000
                out.append("retry %s in %d" % (jid, secs))
        else:
            j["state"] = "done"
            out.append("done %s" % jid)

    p = sum(1 for j in jobs.values() if j["state"] == "pending")
    d = sum(1 for j in jobs.values() if j["state"] == "done")
    x = sum(1 for j in jobs.values() if j["state"] == "dead")
    out.append("pending %d done %d dead %d" % (p, d, x))

    save_state(kv_path, state)
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()

import os
import sys
import threading

MIN = -9223372036854775808
MAX = 9223372036854775807


class SyntaxErr(Exception):
    pass


class EvalErr(Exception):
    pass


def tokenize(s):
    toks = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == ' ':
            i += 1
        elif '0' <= c <= '9':
            j = i
            while j < n and '0' <= s[j] <= '9':
                j += 1
            toks.append(('int', s[i:j]))
            i = j
        elif c == '_' or ('a' <= c <= 'z') or ('A' <= c <= 'Z'):
            j = i
            while j < n and (s[j] == '_' or 'a' <= s[j] <= 'z' or 'A' <= s[j] <= 'Z' or '0' <= s[j] <= '9'):
                j += 1
            toks.append(('name', s[i:j]))
            i = j
        elif c in '+-*/%^(),=':
            toks.append(('op', c))
            i += 1
        else:
            raise SyntaxErr()
    return toks


class Parser:
    def __init__(self, toks):
        self.t = toks
        self.p = 0

    def peek(self):
        return self.t[self.p] if self.p < len(self.t) else (None, None)

    def is_op(self, c):
        k, v = self.peek()
        return k == 'op' and v == c

    def expect_op(self, c):
        if not self.is_op(c):
            raise SyntaxErr()
        self.p += 1

    def expr(self):
        node = self.term()
        while self.is_op('+') or self.is_op('-'):
            op = self.t[self.p][1]
            self.p += 1
            node = ('bin', op, node, self.term())
        return node

    def term(self):
        node = self.factor()
        while self.is_op('*') or self.is_op('/') or self.is_op('%'):
            op = self.t[self.p][1]
            self.p += 1
            node = ('bin', op, node, self.factor())
        return node

    def factor(self):
        if self.is_op('-'):
            self.p += 1
            return ('neg', self.factor())
        return self.power()

    def power(self):
        a = self.atom()
        if self.is_op('^'):
            self.p += 1
            return ('bin', '^', a, self.factor())
        return a

    def atom(self):
        k, v = self.peek()
        if k == 'int':
            self.p += 1
            return ('int', int(v))
        if k == 'name':
            self.p += 1
            if self.is_op('('):
                self.p += 1
                args = [self.expr()]
                while self.is_op(','):
                    self.p += 1
                    args.append(self.expr())
                self.expect_op(')')
                return ('call', v, args)
            return ('var', v)
        if self.is_op('('):
            self.p += 1
            e = self.expr()
            self.expect_op(')')
            return e
        raise SyntaxErr()


def chk(v):
    if v < MIN or v > MAX:
        raise EvalErr('overflow')
    return v


FUNCS = {'min': 2, 'max': 2, 'abs': 1}


def ev(node, env):
    k = node[0]
    if k == 'int':
        return chk(node[1])
    if k == 'var':
        if node[1] not in env:
            raise EvalErr('unknown variable ' + node[1])
        return env[node[1]]
    if k == 'neg':
        return chk(-ev(node[1], env))
    if k == 'call':
        name, args = node[1], node[2]
        if name not in FUNCS:
            raise EvalErr('unknown function ' + name)
        if len(args) != FUNCS[name]:
            raise EvalErr('wrong number of arguments to ' + name)
        vals = [ev(a, env) for a in args]
        if name == 'min':
            return min(vals)
        if name == 'max':
            return max(vals)
        return chk(abs(vals[0]))
    if k == 'bin':
        op = node[1]
        a = ev(node[2], env)
        b = ev(node[3], env)
        if op == '+':
            return chk(a + b)
        if op == '-':
            return chk(a - b)
        if op == '*':
            return chk(a * b)
        if op == '/' or op == '%':
            if b == 0:
                raise EvalErr('division by zero')
            q = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                q = -q
            if op == '/':
                return chk(q)
            return chk(a - b * q)
        if op == '^':
            if b < 0:
                raise EvalErr('negative exponent')
            if a == 0:
                return 1 if b == 0 else 0
            if a == 1:
                return 1
            if a == -1:
                return 1 if b % 2 == 0 else -1
            if b > 64:
                raise EvalErr('overflow')
            return chk(a ** b)
    raise EvalErr('syntax error')


def parse_line(line):
    toks = tokenize(line)
    if toks and toks[0] == ('name', 'let'):
        if len(toks) < 3 or toks[1][0] != 'name' or toks[2] != ('op', '='):
            raise SyntaxErr()
        p = Parser(toks)
        p.p = 3
        e = p.expr()
        if p.p != len(toks):
            raise SyntaxErr()
        return ('let', toks[1][1], e)
    p = Parser(toks)
    e = p.expr()
    if p.p != len(toks):
        raise SyntaxErr()
    return ('expr', e)


def main():
    d = os.environ['INPUT']
    with open(os.path.join(d, 'program.txt'), encoding='utf-8', errors='replace') as f:
        data = f.read()
    lines = data.split('\n')
    env = {}
    out = []
    for idx, raw in enumerate(lines, 1):
        line = raw.rstrip('\r')
        if line.strip() == '':
            continue
        try:
            try:
                st = parse_line(line)
            except (SyntaxErr, RecursionError):
                raise EvalErr('syntax error')
            if st[0] == 'let':
                v = ev(st[2], env)
                env[st[1]] = v
                out.append('%d: %s = %d' % (idx, st[1], v))
            else:
                v = ev(st[1], env)
                out.append('%d: %d' % (idx, v))
        except EvalErr as e:
            out.append('%d: error: %s' % (idx, e.args[0]))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))


if __name__ == '__main__':
    sys.setrecursionlimit(1000000)
    threading.stack_size(512 * 1024 * 1024)
    t = threading.Thread(target=main)
    t.start()
    t.join()

import hashlib
import hmac
import json
import os
import sqlite3
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlsplit

DB_PATH = os.environ["DB"]
SECRETS_DIR = os.environ["SECRETS"]
LOG_PATH = os.environ["LOG"]
PORT = int(os.environ.get("PORT", "8080"))

TYPES = {
    "subscription.created",
    "subscription.activated",
    "payment.failed",
    "subscription.canceled",
}
TRANSITIONS = {
    "subscription.created": ({"none"}, "created"),
    "subscription.activated": ({"created", "past_due"}, "active"),
    "payment.failed": ({"active"}, "past_due"),
    "subscription.canceled": ({"created", "active", "past_due"}, "canceled"),
}

LOCK = threading.Lock()
LOG_LOCK = threading.Lock()


def connect():
    conn = sqlite3.connect(DB_PATH, isolation_level=None, check_same_thread=False, timeout=30)
    conn.execute(
        "CREATE TABLE IF NOT EXISTS events ("
        "id TEXT PRIMARY KEY, subscription TEXT NOT NULL, seq INTEGER NOT NULL, "
        "type TEXT NOT NULL, status TEXT NOT NULL)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS events_sub ON events(subscription, status, seq)"
    )
    conn.execute(
        "CREATE TABLE IF NOT EXISTS subs ("
        "id TEXT PRIMARY KEY, state TEXT NOT NULL, seq INTEGER NOT NULL, history TEXT NOT NULL)"
    )
    return conn


CONN = connect()


def write_log(line):
    with LOG_LOCK:
        with open(LOG_PATH, "a", encoding="utf-8") as f:
            f.write(line + "\n")


def read_secret():
    with open(os.path.join(SECRETS_DIR, "webhook.key"), "rb") as f:
        data = f.read()
    if data.endswith(b"\r\n"):
        data = data[:-2]
    elif data.endswith(b"\n"):
        data = data[:-1]
    return data


def valid_event(ev):
    if not isinstance(ev, dict):
        return False
    if not isinstance(ev.get("id"), str):
        return False
    if not isinstance(ev.get("type"), str) or ev["type"] not in TYPES:
        return False
    if not isinstance(ev.get("subscription"), str):
        return False
    seq = ev.get("seq")
    if isinstance(seq, bool) or not isinstance(seq, int) or seq < 1:
        return False
    return True


def process_event(ev):
    """Returns (status_code, body, log_lines)."""
    logs = []
    conn = CONN
    conn.execute("BEGIN IMMEDIATE")
    try:
        if conn.execute("SELECT 1 FROM events WHERE id=?", (ev["id"],)).fetchone():
            conn.execute("COMMIT")
            return 200, {"status": "duplicate"}, logs
        sub = ev["subscription"]
        row = conn.execute("SELECT state, seq, history FROM subs WHERE id=?", (sub,)).fetchone()
        if row:
            state, last, history = row[0], row[1], json.loads(row[2])
        else:
            state, last, history = "none", 0, []
        seq = ev["seq"]
        if seq <= last:
            conn.execute(
                "INSERT INTO events(id, subscription, seq, type, status) VALUES (?,?,?,?,?)",
                (ev["id"], sub, seq, ev["type"], "stale"),
            )
            conn.execute("COMMIT")
            return 200, {"status": "stale"}, logs
        if seq > last + 1:
            conn.execute(
                "INSERT INTO events(id, subscription, seq, type, status) VALUES (?,?,?,?,?)",
                (ev["id"], sub, seq, ev["type"], "queued"),
            )
            conn.execute("COMMIT")
            return 202, {"status": "queued"}, logs

        conn.execute(
            "INSERT INTO events(id, subscription, seq, type, status) VALUES (?,?,?,?,?)",
            (ev["id"], sub, seq, ev["type"], "applied"),
        )
        count = 0
        cur_id, cur_type, cur_seq = ev["id"], ev["type"], seq
        while True:
            allowed, target = TRANSITIONS[cur_type]
            if state in allowed:
                state = target
                history.append(state)
            else:
                logs.append("invalid transition " + cur_id)
            last = cur_seq
            count += 1
            # Any other queued events at or below the new last seq are now stale.
            conn.execute(
                "UPDATE events SET status='stale' WHERE subscription=? AND status='queued' AND seq<=?",
                (sub, last),
            )
            nxt = conn.execute(
                "SELECT id, type, seq FROM events WHERE subscription=? AND status='queued' AND seq=? "
                "ORDER BY rowid LIMIT 1",
                (sub, last + 1),
            ).fetchone()
            if not nxt:
                break
            cur_id, cur_type, cur_seq = nxt
            conn.execute("UPDATE events SET status='applied' WHERE id=?", (cur_id,))
        conn.execute(
            "INSERT INTO subs(id, state, seq, history) VALUES (?,?,?,?) "
            "ON CONFLICT(id) DO UPDATE SET state=excluded.state, seq=excluded.seq, history=excluded.history",
            (sub, state, last, json.dumps(history)),
        )
        conn.execute("COMMIT")
        return 200, {"status": "applied", "applied": count}, logs
    except Exception:
        try:
            conn.execute("ROLLBACK")
        except Exception:
            pass
        raise


def get_sub(sub_id):
    with LOCK:
        row = CONN.execute("SELECT state, seq, history FROM subs WHERE id=?", (sub_id,)).fetchone()
    if not row:
        return 404, {"error": "not found"}
    return 200, {"id": sub_id, "state": row[0], "seq": row[1], "history": json.loads(row[2])}


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):
        pass

    def send_json(self, code, obj):
        data = json.dumps(obj).encode("utf-8")
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def read_body(self):
        length = self.headers.get("content-length")
        try:
            n = int(length) if length else 0
        except ValueError:
            n = 0
        return self.rfile.read(n) if n > 0 else b""

    def path_only(self):
        return urlsplit(self.path).path

    def handle_any(self):
        body = self.read_body()
        path = self.path_only()
        try:
            if self.command == "POST" and path == "/webhooks":
                return self.webhook(body)
            if self.command == "GET" and path.startswith("/subscriptions/"):
                raw = path[len("/subscriptions/"):]
                if raw:
                    code, obj = get_sub(unquote(raw))
                    return self.send_json(code, obj)
            self.send_json(404, {"error": "not found"})
        except Exception:
            self.send_json(500, {"error": "internal error"})

    def webhook(self, body):
        sig = self.headers.get("x-signature")
        ok = False
        if sig is not None:
            try:
                secret = read_secret()
                expected = "sha256=" + hashlib.sha256(secret + b"." + body).hexdigest()
                ok = hmac.compare_digest(sig.encode("utf-8"), expected.encode("utf-8"))
            except Exception:
                ok = False
        if not ok:
            write_log("rejected signature")
            return self.send_json(401, {"error": "bad signature"})
        try:
            ev = json.loads(body.decode("utf-8"))
        except Exception:
            ev = None
        if not valid_event(ev):
            return self.send_json(400, {"error": "invalid event"})
        with LOCK:
            code, obj, logs = process_event(ev)
        for line in logs:
            write_log(line)
        self.send_json(code, obj)

    do_GET = handle_any
    do_POST = handle_any
    do_PUT = handle_any
    do_DELETE = handle_any
    do_PATCH = handle_any
    do_HEAD = handle_any
    do_OPTIONS = handle_any


def main():
    server = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    server.daemon_threads = True
    server.serve_forever()


if __name__ == "__main__":
    main()
